CREATE DATABASE IF NOT EXISTS entre_paginas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE entre_paginas;
CREATE TABLE usuarios(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,usuario VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,clave VARCHAR(255) NOT NULL,avatar VARCHAR(255),bio TEXT,rol ENUM('lector','moderador','admin') NOT NULL DEFAULT 'lector',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE preferencias_lectura(usuario_id BIGINT UNSIGNED NOT NULL,genero VARCHAR(60) NOT NULL,PRIMARY KEY(usuario_id,genero),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE autores(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL);
CREATE TABLE libros(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,autor_id BIGINT UNSIGNED NULL,titulo VARCHAR(220) NOT NULL,portada VARCHAR(255),sinopsis TEXT,isbn VARCHAR(20),FOREIGN KEY(autor_id) REFERENCES autores(id) ON DELETE SET NULL);
CREATE TABLE categorias(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(90) NOT NULL UNIQUE);
CREATE TABLE publicaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,libro_id BIGINT UNSIGNED NULL,categoria_id BIGINT UNSIGNED NULL,tipo ENUM('resena','frase','foto','texto') NOT NULL DEFAULT 'texto',titulo VARCHAR(220),contenido TEXT NOT NULL,imagen VARCHAR(255),calificacion TINYINT UNSIGNED NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(libro_id) REFERENCES libros(id) ON DELETE SET NULL,FOREIGN KEY(categoria_id) REFERENCES categorias(id) ON DELETE SET NULL,INDEX(creado_en));
CREATE TABLE comentarios(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publicacion_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,contenido TEXT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(publicacion_id) REFERENCES publicaciones(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE reacciones(usuario_id BIGINT UNSIGNED NOT NULL,publicacion_id BIGINT UNSIGNED NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(usuario_id,publicacion_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(publicacion_id) REFERENCES publicaciones(id) ON DELETE CASCADE);
CREATE TABLE guardados(usuario_id BIGINT UNSIGNED NOT NULL,publicacion_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(usuario_id,publicacion_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(publicacion_id) REFERENCES publicaciones(id) ON DELETE CASCADE);
CREATE TABLE bibliotecas(usuario_id BIGINT UNSIGNED NOT NULL,libro_id BIGINT UNSIGNED NOT NULL,estado ENUM('pendiente','leyendo','terminado') NOT NULL DEFAULT 'pendiente',progreso TINYINT UNSIGNED NOT NULL DEFAULT 0,fecha_inicio DATE,fecha_fin DATE,PRIMARY KEY(usuario_id,libro_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(libro_id) REFERENCES libros(id) ON DELETE CASCADE);
CREATE TABLE clubes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,creador_id BIGINT UNSIGNED NOT NULL,nombre VARCHAR(150) NOT NULL,descripcion TEXT,imagen VARCHAR(255),creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creador_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE miembros_club(club_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,rol ENUM('miembro','admin') DEFAULT 'miembro',PRIMARY KEY(club_id,usuario_id),FOREIGN KEY(club_id) REFERENCES clubes(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE mensajes_club(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,contenido TEXT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(club_id) REFERENCES clubes(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE conversaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE participantes_conversacion(conversacion_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(conversacion_id,usuario_id),FOREIGN KEY(conversacion_id) REFERENCES conversaciones(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE mensajes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversacion_id BIGINT UNSIGNED NOT NULL,emisor_id BIGINT UNSIGNED NOT NULL,contenido TEXT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversacion_id) REFERENCES conversaciones(id) ON DELETE CASCADE,FOREIGN KEY(emisor_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE notificaciones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NULL,tipo VARCHAR(40) NOT NULL,contenido VARCHAR(255) NOT NULL,leida BOOLEAN DEFAULT FALSE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(actor_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE retos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,anio SMALLINT NOT NULL,meta SMALLINT UNSIGNED NOT NULL DEFAULT 12,UNIQUE(usuario_id,anio),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE configuracion(clave VARCHAR(100) PRIMARY KEY,valor TEXT);
